            <div class="the-menu__footer">
              <?php
              $available_some = [ 'Facebook', 'Instagram', 'LinkedIn', 'Twitter' ];
  
              $some_items = [];
              foreach ( $available_some as $platform ) {
                $field = sts_option( 'company.some.' . strtolower( $platform ) );
                
                if ( ! empty( $field ) ) {
                    $some_items[] = [
                      'name' => $platform,
                      'url' => $field
                    ];
                }
              }; 
  
              if ( ! empty( $some_items ) ) { ?>
                <ul class="row gap-1">
                  <?php foreach ( $some_items as $item ) { ?>
                    <li>
                      <a href="<?= esc_url( $item[ 'url' ] ); ?>">
                        <?= $item[ 'name' ]; ?>
                      </a>
                    </li>
                  <?php } ?>
                </ul>
              <?php }; 
  
              $phone_number = sts_option( 'contact.phone' );
              $email        = sts_option( 'contact.email' );
              
              if ( $phone_number || $email ) { ?>
                <ul class="row gap-1">
                  <?php if ( $phone_number ) { ?>
                    <li>
                      <a href="tel:<?= esc_attr( $phone_number ); ?>">
                        <?= esc_html( get_theme_string( 'Ring til os' ) ); ?> 
                      </a>
                    </li>
                  <?php } 

                  if ( $email ) { ?>
